def skill(robot):
    robot.set_wind_correction(0, 0)
    g = robot.ground_robot_position()
    if not g:
        return False
    f = robot.fly_to(g[0], g[1], 1.3)
    if not f:
        return False
    robot.set_wind_correction(max(-3, min(3, -6 * (f[0] - g[0]))), max(-3, min(3, -6 * (f[1] - g[1]))))
    p1 = robot.find_pad()
    g1 = robot.ground_robot_position()
    if not p1 or not g1:
        return False
    f = robot.fly_to(g1[0], g1[1], 1.3)
    if not f:
        return False
    p2 = robot.find_pad()
    if not p2:
        return False
    vx = (p2[0] - p1[0]) / 3.0
    vy = (p2[1] - p1[1]) / 3.0
    f = robot.fly_to(p2[0] + vx * 3, p2[1] + vy * 3, 1.3)
    if not f:
        return False
    p3 = robot.find_pad()
    if not p3:
        return robot.land_at(p2[0] + vx * 5, p2[1] + vy * 5)
    vx = (p3[0] - p2[0]) / 3.0
    vy = (p3[1] - p2[1]) / 3.0
    return robot.land_at(p3[0] + vx * 2, p3[1] + vy * 2)

